function stworzKota(imie) {
  return {
    imie,
    miauknij() {
      return `${imie} mowi: Miau!`;
    },
  };
}

const kot = stworzKota("Filemon");
console.log(kot.miauknij()); // "Filemon mowi: Miau!"

class Kot {
  constructor(imie) {
    this.imie = imie;
  }
  miauknij() {
    return `${this.imie} mowi: Miau!`;
  }
}

function stworzKota(imie) {
  return { imie, miauknij() { return `${imie} mowi: Miau!`; } };
}

const kotZKlasy = new Kot("Reksio");
const kotZFabryki = stworzKota("Filemon");

console.log(kotZKlasy instanceof Kot);   // true
console.log(kotZFabryki instanceof Kot); // false
// Obiekt z fabryki to zwykly obiekt literalowy, ktory nigdy nie zostal
// stworzony PRZEZ class Kot, wiec instanceof Kot dla niego zawsze zwraca
// false, mimo ze funkcjonalnie "zachowuje sie" bardzo podobnie.

function stworzSamochod(marka, przebiegPoczatkowy = 0) {
  let przebieg = przebiegPoczatkowy; // "prywatna" zmienna dzieki closure
  return {
    marka,
    jedz(km) {
      przebieg += km;
    },
    pobierzPrzebieg() {
      return przebieg;
    },
  };
}

const samochod = stworzSamochod("Toyota");
samochod.jedz(50);
console.log(samochod.pobierzPrzebieg()); // 50

class Ksztalt4 {
  constructor(nazwa) {
    this.nazwa = nazwa;
  }
  opis() {
    return `Ksztalt: ${this.nazwa}`;
  }
}

function stworzKsztalt(nazwa) {
  return {
    nazwa,
    opis() {
      return `Ksztalt: ${this.nazwa}`;
    },
  };
}

const zKlasy = new Ksztalt4("Kolo");
const zFabryki = stworzKsztalt("Kwadrat");

console.log(zKlasy.opis());   // "Ksztalt: Kolo"
console.log(zFabryki.opis()); // "Ksztalt: Kwadrat" - identyczne dzialanie

// class daje "za darmo" dwie mozliwosci, ktorych funkcja fabrykujaca nie
// posiada w naturalny sposob:
// 1. Dziedziczenie (extends/super) - class moze latwo "rozszerzyc" inna
//    klase, dziedziczac jej pola i metody oraz nadpisujac wybrane z nich.
//    Funkcje fabrykujace nie maja wbudowanego, prostego mechanizmu do
//    tworzenia takich hierarchii (wymagalyby recznego "skladania" obiektow).
// 2. instanceof - obiekty stworzone przez new Klasa(...) sa instanceof
//    Klasa, co pozwala latwo sprawdzic 'typ' obiektu w kodzie (np. w
//    catch (error) { if (error instanceof BladWalidacji) {...} }).
//    Obiekty z fabryki nigdy nie sa instanceof zadnej konkretnej 'klasy
//    pojeciowej', tylko ogolnego Object.

function stworzLicznik() {
  let wartosc = 0;
  return {
    increment() {
      wartosc++;
    },
    pobierzWartosc() {
      return wartosc;
    },
  };
}

const licznik = stworzLicznik();
licznik.increment();
licznik.increment();
licznik.increment();
console.log(licznik.pobierzWartosc()); // 3

function stworzLicznik() {
  let wartosc = 0;
  return {
    increment() { wartosc++; },
    pobierzWartosc() { return wartosc; },
  };
}

const licznikA = stworzLicznik();
const licznikB = stworzLicznik();

licznikA.increment();
licznikA.increment();

for (let i = 0; i < 5; i++) {
  licznikB.increment();
}

console.log(licznikA.pobierzWartosc()); // 2
console.log(licznikB.pobierzWartosc()); // 5 - calkowicie niezalezne od licznikA

// Warto wybrac funkcje fabrykujaca zamiast class, gdy:
// 1. Nie potrzebujesz dziedziczenia (extends/super) ani instanceof do
//    sprawdzania typow - tworzysz proste, niezalezne obiekty bez potrzeby
//    hierarchii pojeciowej "jest-typem".
// 2. Preferujesz styl bardziej "funkcyjny" niz obiektowy - np. w kodzie
//    zgodnym z konwencjami React (hooki jak useState wykorzystuja closure,
//    nie class) lub gdy zespol/projekt generalnie unika class na rzecz
//    zwyklych funkcji i obiektow.

function stworzOsobe(imie, wiek) {
  return {
    imie,
    wiek,
    przedstaw() {
      return imie + ", " + wiek + " lat";
    }
  };
}

class Osoba {
  constructor(imie, wiek) {
    this.imie = imie;
    this.wiek = wiek;
  }
  przedstaw() {
    return this.imie + ", " + this.wiek + " lat";
  }
}

const a = stworzOsobe("Ala", 30);
const b = new Osoba("Jan", 40);
console.log(a.przedstaw(), b.przedstaw());  // -> "Ala, 30 lat" "Jan, 40 lat"
console.log(a instanceof Object, b instanceof Osoba); // -> true true

function stworzKonto(saldoStartowe) {
  let saldo = saldoStartowe;

  return {
    wplac(k) {
      saldo += k;
    },
    wyplac(k) {
      if (k > saldo) return false;
      saldo -= k;
      return true;
    },
    stan() {
      return saldo;
    }
  };
}

const konto = stworzKonto(100);
konto.wplac(50);
console.log(konto.wyplac(30));  // -> true
console.log(konto.wyplac(500)); // -> false
console.log(konto.stan());      // -> 120
console.log(konto.saldo);       // -> undefined

function stworzKonto(s) {
  let saldo = s;
  return {
    wplac(k) { saldo += k; },
    stan() { return saldo; }
  };
}

const konto = stworzKonto(10);
const { wplac, stan } = konto;
wplac(5);
console.log(stan()); // -> 15
// Metody nie uzywaja this, wiec po wyciagnieciu nadal dzialaja - dane sa w domknieciu.

class Licznik {
  #n = 0;
  inc() {
    return ++this.#n;
  }
}

function stworzLicznik() {
  let n = 0;
  return {
    inc() {
      return ++n;
    }
  };
}

console.log(new Licznik().inc === new Licznik().inc);  // -> true  (jedna metoda w prototypie)
console.log(stworzLicznik().inc === stworzLicznik().inc); // -> false (nowa funkcja dla kazdego obiektu)
// Przy bardzo wielu obiektach fabryka zuzywa wiecej pamieci - kazdy obiekt ma wlasne kopie metod.

const stworzLatajace = () => ({ lec: () => "lece" });
const stworzPlywajace = () => ({ plyn: () => "plyne" });

const stworzKaczke = () => ({
  ...stworzLatajace(),
  ...stworzPlywajace(),
  kwacz: () => "kwa"
});

const kaczka = stworzKaczke();
console.log(kaczka.lec(), kaczka.plyn(), kaczka.kwacz()); // -> "lece" "plyne" "kwa"

const protoOsoby = {
  przedstaw() {
    return "Jestem " + this.imie;
  }
};

function stworzOsobe(imie) {
  const o = Object.create(protoOsoby);
  o.imie = imie;
  return o;
}

const a = stworzOsobe("Ala");
const b = stworzOsobe("Jan");
console.log(a.przedstaw());                       // -> "Jestem Ala"
console.log(protoOsoby.isPrototypeOf(a));         // -> true
console.log(a.przedstaw === b.przedstaw);         // -> true (wspolna metoda z prototypu)

"use strict";

function stworzPunkt(x, y) {
  return Object.freeze({ x, y });
}

const p = stworzPunkt(1, 2);
try {
  p.x = 100;
} catch (e) {
  console.log(e.name); // -> "TypeError"
}
console.log(p.x);      // -> 1

function stworzUstawienia(opcje = {}) {
  return { jezyk: "pl", motyw: "jasny", ...opcje };
}

console.log(stworzUstawienia());                    // -> { jezyk: "pl", motyw: "jasny" }
console.log(stworzUstawienia({ motyw: "ciemny" })); // -> { jezyk: "pl", motyw: "ciemny" }

function stworzStos() {
  const elementy = [];

  return {
    dodaj(x) {
      elementy.push(x);
    },
    zdejmij() {
      return elementy.pop();
    },
    rozmiar() {
      return elementy.length;
    }
  };
}

const s = stworzStos();
s.dodaj(1);
s.dodaj(2);
console.log(s.zdejmij());  // -> 2
console.log(s.rozmiar());  // -> 1
console.log(s.elementy);   // -> undefined

function stworzEmiter() {
  const handlery = {};

  return {
    on(nazwa, fn) {
      (handlery[nazwa] ||= []).push(fn);
    },
    emit(nazwa, ...args) {
      (handlery[nazwa] || []).forEach(fn => fn(...args));
    }
  };
}

const e = stworzEmiter();
e.on("hej", x => console.log("a: " + x));
e.on("hej", x => console.log("b: " + x));
e.emit("hej", "swiat");
// -> "a: swiat"
// -> "b: swiat"

function stworzFigure(typ, r) {
  if (typ === "kolo") return { pole: () => Math.PI * r ** 2 };
  if (typ === "kwadrat") return { pole: () => r ** 2 };
  throw new Error("nieznany typ: " + typ);
}

console.log(stworzFigure("kwadrat", 3).pole()); // -> 9
console.log(Math.round(stworzFigure("kolo", 1).pole() * 100) / 100); // -> 3.14
try {
  stworzFigure("trojkat", 1);
} catch (e) {
  console.log(e.message); // -> "nieznany typ: trojkat"
}

class Osoba {
  constructor(imie, wiek) {
    this.imie = imie;
    this.wiek = wiek;
  }

  static zTekstu(tekst) {
    const [imie, wiek] = tekst.split(":");
    return new Osoba(imie, Number(wiek));
  }
}

function stworzOsobeZTekstu(tekst) {
  const [imie, wiek] = tekst.split(":");
  return { imie, wiek: Number(wiek) };
}

console.log(Osoba.zTekstu("Jan:30"));        // -> instancja klasy Osoba
console.log(stworzOsobeZTekstu("Jan:30"));   // -> zwykly obiekt
console.log(Osoba.zTekstu("Jan:30") instanceof Osoba); // -> true

class Prostokat {
  constructor(a, b) {
    this.a = a;
    this.b = b;
  }
  pole() {
    return this.a * this.b;
  }
}

function stworzProstokat(a, b) {
  return {
    a,
    b,
    pole() {
      return a * b;
    }
  };
}

console.log(new Prostokat(3, 4).pole()); // -> 12
console.log(stworzProstokat(3, 4).pole()); // -> 12

function stworzOsobe(imie) {
  let wiek = 0;

  return {
    imie,
    get wiek() {
      return wiek;
    },
    set wiek(v) {
      if (v < 0) throw new RangeError("wiek nie moze byc ujemny");
      wiek = v;
    }
  };
}

const o = stworzOsobe("Ala");
o.wiek = 30;
console.log(o.wiek); // -> 30

try {
  o.wiek = -1;
} catch (e) {
  console.log(e.name); // -> "RangeError"
}

function stworzMnoznik(n) {
  return x => x * n;
}

const razy2 = stworzMnoznik(2);
const razy10 = stworzMnoznik(10);

console.log([1, 2, 3].map(razy2));  // -> [2, 4, 6]
console.log([1, 2, 3].map(razy10)); // -> [10, 20, 30]
// Do prostego zachowania z zapamietanym parametrem klasa jest zbedna - wystarczy domkniecie.

const licznik = (function () {
  let n = 0;
  return {
    inc() {
      return ++n;
    },
    wartosc() {
      return n;
    }
  };
})();

licznik.inc();
licznik.inc();
licznik.inc();
console.log(licznik.wartosc()); // -> 3
// Przydatne, gdy potrzebny jest dokladnie jeden obiekt z ukrytym stanem (bez tworzenia klasy).

class Osoba {
  constructor(imie, wiek) {
    this.imie = imie;
    this.wiek = wiek;
  }
}

function stworzOsobe(imie, wiek) {
  return {
    imie,
    pobierzWiek() {
      return wiek;
    }
  };
}

console.log(JSON.stringify(new Osoba("Ala", 30)));  // -> {"imie":"Ala","wiek":30}
console.log(JSON.stringify(stworzOsobe("Ala", 30))); // -> {"imie":"Ala"}
// Dane z domkniecia nie sa wlasciwosciami obiektu - nie trafiaja do JSON-a (ani do Object.keys).

function stworzLicznik() {
  let n = 0;
  return {
    inc() { n++; },
    wartosc() { return n; }
  };
}

const licznik = stworzLicznik();
[1, 2, 3].forEach(licznik.inc);
console.log(licznik.wartosc()); // -> 3
// Metoda z klasy uzywajaca this po wyciagnieciu straciloby this - tutaj stan siedzi w domknieciu.

class Uzytkownik {
  constructor(imie) {
    this.imie = imie;
  }
  pozdrow() {
    return "Czesc, " + this.imie;
  }
}

const stworzUzytkownika = (...args) => new Uzytkownik(...args);

const u = stworzUzytkownika("Ala");
console.log(u.pozdrow());            // -> "Czesc, Ala"
console.log(u instanceof Uzytkownik); // -> true
// Fabryka ukrywa detal implementacji (new), a klasa daje instanceof i wspolne metody w prototypie.

function stworzSejf(kod) {
  return {
    otworz(proba) {
      return proba === kod;
    },
    toString() {
      return "Sejf";
    }
  };
}

const s = stworzSejf("1234");
console.log(String(s));          // -> "Sejf"
console.log(s.otworz("zly"));    // -> false
console.log(s.otworz("1234"));   // -> true

// KLASA: dziedziczenie (extends), instanceof, metody wspoldzielone w prototypie (mniej pamieci)
class LicznikKlasa {
  #n = 0;
  inc() { return ++this.#n; }
}

// FABRYKA: brak this i new, prywatnosc przez domkniecie, latwe przekazywanie metod jako callbackow
function stworzLicznik() {
  let n = 0;
  return { inc: () => ++n };
}

console.log(new LicznikKlasa().inc());  // -> 1
console.log(stworzLicznik().inc());     // -> 1

function stworzPamiec(fn) {
  const cache = {};
  return function (x) {
    if (!(x in cache)) cache[x] = fn(x);
    return cache[x];
  };
}

let wywolania = 0;
const kwadrat = stworzPamiec(x => {
  wywolania++;
  return x * x;
});

console.log(kwadrat(2), kwadrat(2), kwadrat(3)); // -> 4 4 9
console.log(wywolania);                          // -> 2

